B.aWJ=new A.cV("cielo_tinta",B.dA,"Cielo de tinta","Sumi-e puro. Sin color, solo grises y silencio.",B.dM)
B.aWI=new A.cV("cielo_sangre",B.dA,"Crep\xfasculo de sangre","El cielo antes de una batalla que nadie va a librar.",B.dl)
B.aWY=new A.cV("cielo_cosmos",B.dA,"Nebulosa","El templo bajo una galaxia que no deber\xeda verse.",B.eY)
B.aWN=new A.cV("cielo_oro",B.dA,"Amanecer de oro","La luz que solo ven los que madrugan de verdad.",B.fu)
B.aX4=new A.cV("luna_velada",B.eo,"Luna velada","Detr\xe1s de las nubes. Est\xe1, aunque no se vea entera.",B.dM)
B.aWD=new A.cV("luna_gemela",B.eo,"Lunas gemelas","Dos lunas. Nadie ha explicado nunca de d\xf3nde sali\xf3 la segunda.",B.eY)
B.aWF=new A.cV("luna_dorada",B.eo,"Luna de oro","La noche que el templo termin\xf3 de construirse.",B.fu)
B.aX5=new A.cV("luna_kanji",B.eo,"Luna grabada","Con el car\xe1cter \u529b \u2014fuerza\u2014 marcado en su cara.",B.dl)
B.aWA=new A.cV("mont_volcan",B.f9,"Volc\xe1n humeante","Lleva doscientos a\xf1os a punto de despertar.",B.dl)
B.aWG=new A.cV("mont_islas",B.f9,"Islas suspendidas","Rocas que flotan porque a nadie se le ocurri\xf3 prohibirlo.",B.eY)
B.aWC=new A.cV("mont_agujas",B.f9,"Agujas de piedra","Columnas verticales sobre la niebla.",B.dM)
B.aWS=new A.cV("mont_nevadas",B.f9,"Cumbres nevadas","Blanco hasta media ladera todo el a\xf1o.",B.dM)
B.aXd=new A.cV("agua_seca",B.fa,"Jard\xedn seco","Arena rastrillada en lugar de agua. Karesansui.",B.dl)
B.aWy=new A.cV("agua_laca",B.fa,"Estanque de laca","Rojo profundo, denso, quieto.",B.dM)
B.aX0=new A.cV("agua_espejo",B.fa,"Espejo perfecto","Refleja el cielo entero sin una sola onda.",B.eY)
B.aX_=new A.cV("agua_oro",B.fa,"Corriente dorada","El agua arrastra polvo de oro desde la monta\xf1a.",B.fu)
B.aWx=new A.cV("est_linterna",B.dV,"Linterna de piedra","T\u014dr\u014d. Encendida desde hace m\xe1s a\xf1os de los que nadie cuenta.",B.dM)
B.aXc=new A.cV("est_campana",B.dV,"La gran campana","Bonsh\u014d. Se golpea 108 veces al terminar el a\xf1o.",B.dl)
B.aX8=new A.cV("est_castillo",B.dV,"Castillo","Tejados escalonados sobre un muro que nadie tom\xf3.",B.eY)
B.aWH=new A.cV("est_torii_doble",B.dV,"Sendero de torii","Puerta tras puerta, hasta que se pierde la cuenta.",B.fu)
B.aWX=new A.cV("veg_arce",B.ep,"Arce rojo","Momiji en oto\xf1o. Dura tres semanas al a\xf1o.",B.dM)
B.aX2=new A.cV("veg_glicina",B.ep,"Glicinas","Racimos violeta colgando sobre el agua.",B.dl)
B.aXf=new A.cV("veg_loto",B.ep,"Lotos","Nacen del barro y salen limpios. Por eso est\xe1n aqu\xed.",B.dl)
B.aWP=new A.cV("veg_sakura_nocturno",B.ep,"Cerezo nocturno","Yozakura: el cerezo iluminado por dentro.",B.eY)
B.aXe=new A.cV("cri_luciernagas",B.d2,"Luci\xe9rnagas","Hotaru. Aparecen una semana al a\xf1o y desaparecen.",B.dM)
B.aX9=new A.cV("cri_cuervos",B.d2,"Cuervos","Tres. Siempre tres, y siempre mirando al mismo sitio.",B.dM)
B.aX6=new A.cV("cri_espiritus",B.d2,"Fuegos fatuos","Hitodama. Almas que se quedaron a entrenar.",B.dl)
B.aWB=new A.cV("cri_tigre",B.d2,"Tigre entre bamb\xfa","No se ve entero nunca. Solo las rayas y los ojos.",B.fu)
B.aXa=new A.cV("cli_petalos",B.eq,"Lluvia de p\xe9talos","Hanafubuki: la tormenta de flores.",B.dM)
B.aX7=new A.cV("cli_lluvia",B.eq,"Lluvia fina","La que no molesta y lo cambia todo.",B.dM)
B.aX3=new A.cV("cli_ceniza",B.eq,"Ceniza","Cae despacio desde el volc\xe1n. Nadie se va por eso.",B.dl)
B.aWU=new A.cV("cli_polvo_oro",B.eq,"Polvo de oro","El aire brilla. No hay explicaci\xf3n y no hace falta.",B.fu)
B.aWQ=new A.cV("cielo_fugaces",B.dA,"Estrellas fugaces","Pide un deseo: aqu\xed se cumplen entrenando.",B.dl)
B.aWE=new A.cV("cielo_linternas",B.dA,"Linternas al cielo","Cientos de luces suben despacio. Cada una, una promesa.",B.eY)
B.aWV=new A.cV("luna_halo",B.eo,"Halo lunar","Un anillo de hielo alrededor de la luna. Dicen que anuncia cambios.",B.dl)
B.aWZ=new A.cV("mont_cristal",B.f9,"Picos de cristal","Monta\xf1as que guardan la luz de la luna por dentro.",B.eY)
B.aWO=new A.cV("agua_toro",B.fa,"R\xedo de linternas","T\u014dr\u014d nagashi: faroles que el agua lleva hacia el mar.",B.eY)
B.aWW=new A.cV("agua_olas",B.fa,"Mar embravecido","Olas que rompen sin descanso. Como t\xfa.",B.dl)
B.aXb=new A.cV("est_faroles",B.dV,"Calle de faroles","Ch\u014dchin rojos que se mecen con el viento de la tarde.",B.dl)
B.aWz=new A.cV("veg_sauce",B.ep,"Sauce llor\xf3n","Sus ramas acarician el agua al ritmo del viento.",B.dM)
B.aWR=new A.cV("cri_mariposas",B.d2,"Mariposas de luz","Revolotean cerca de quien entrena con constancia.",B.dM)
B.aWT=new A.cV("cri_grullas_papel",B.d2,"Grullas de papel","Mil grullas dobladas, mil deseos.",B.dl)
B.aWK=new A.cV("cri_fenix",B.d2,"F\xe9nix","H\u014d-\u014d: renace de sus cenizas, como cada lunes.",B.fu)
