B.Oi={press_banca:0,press_inclinado_mancuerna:1,aperturas_polea:2,fondos:3,dominadas:4,remo_barra:5,jalon_polea:6,remo_mancuerna:7,peso_muerto:8,press_militar:9,elevaciones_laterales:10,pajaro:11,curl_barra:12,curl_martillo:13,extension_triceps_polea:14,press_frances:15,curl_muneca:16,sentadilla:17,prensa:18,zancadas:19,curl_femoral:20,elevacion_talones:21,plancha:22,elevacion_piernas:23,rueda_abdominal:24,flexiones:25,flexiones_diamante:26,sentadilla_goblet:27,sentadilla_libre:28,peso_muerto_rumano:29,press_hombro_mancuerna:30,curl_mancuerna:31,extension_triceps_mancuerna:32,remo_banda:33,puente_gluteo:34,talones_libre:35,crunch:36,flexiones_rodillas:37,flexiones_inclinadas:38,flexiones_declinadas:39,remo_mesa:40,superman:41,remo_garrafa:42,flexiones_pica:43,press_banda:44,elevaciones_botellas:45,curl_banda:46,curl_garrafa:47,fondos_silla:48,curl_muneca_garrafa:49,paseo_granjero:50,escaladores:51,tijeras:52,zancada_atras:53,sentadilla_bulgara:54,sentadilla_pared:55,subida_escalon:56,sentadilla_salto:57,puente_una_pierna:58,talones_una_pierna:59,saltitos:60,saltos_tijera:61}
B.aEZ=s(["T\xfambate con los ojos bajo la barra y los pies firmes en el suelo.","Junta las esc\xe1pulas y agarra un poco m\xe1s ancho que los hombros.","Baja controlado hasta rozar el pecho, a la altura del estern\xf3n.","Empuja hacia arriba y un poco hacia atr\xe1s hasta estirar los brazos."],t.s)
B.aza=s(["Rebotar la barra en el pecho.","Despegar la cadera del banco."],t.s)
B.aoy=new A.cn(B.aEZ,B.aza,"Suelta el aire al subir o empujar.")
B.aBq=s(["Banco a 30\u201345\xb0. Mancuernas a la altura del pecho alto.","Codos a unos 45\xb0 del cuerpo, no abiertos en cruz.","Empuja hasta casi juntar las mancuernas arriba.","Baja lento hasta sentir el estiramiento del pecho."],t.s)
B.aAc=s(["Inclinar demasiado el banco (trabaja m\xe1s el hombro)."],t.s)
B.api=new A.cn(B.aBq,B.aAc,"Suelta el aire al subir o empujar.")
B.az2=s(["Poleas altas, un pie adelantado y el pecho erguido.","Codos ligeramente doblados durante todo el recorrido.","Cierra los brazos en arco hasta juntar las manos delante.","Vuelve despacio hasta sentir el pecho estirado."],t.s)
B.avg=s(["Convertirlo en un press doblando los codos."],t.s)
B.apf=new A.cn(B.az2,B.avg,"Suelta el aire al subir o empujar.")
B.aKj=s(["Sube a las paralelas con los brazos estirados y hombros abajo.","Inclina un poco el torso hacia delante.","Baja hasta que los codos lleguen a unos 90\xb0.","Empuja hasta estirar los brazos sin bloquear de golpe."],t.s)
B.aA_=s(["Bajar demasiado si te molesta el hombro.","Encoger los hombros hacia las orejas."],t.s)
B.apd=new A.cn(B.aKj,B.aA_,"Suelta el aire al subir o empujar.")
B.aIt=s(["Cu\xe9lgate con agarre algo m\xe1s ancho que los hombros.","Baja los hombros y aprieta el abdomen antes de tirar.","Tira llevando los codos hacia las costillas hasta pasar la barbilla.","Baja completo y controlado, sin soltarte de golpe."],t.s)
B.awZ=s(["Balancearse para ayudarse.","Hacer medias repeticiones."],t.s)
B.aoI=new A.cn(B.aIt,B.awZ,"Suelta el aire al subir.")
B.aHt=s(["Rodillas un poco flexionadas, torso inclinado unos 45\xb0 y espalda recta.","La barra cuelga bajo los hombros.","Tira hacia el ombligo llevando los codos atr\xe1s.","Aprieta la espalda arriba un instante y baja controlado."],t.s)
B.aDg=s(["Redondear la espalda.","Levantar el torso para tirar."],t.s)
B.aoZ=new A.cn(B.aHt,B.aDg,"Suelta el aire al subir o empujar.")
B.ax2=s(["Si\xe9ntate con los muslos fijos bajo el apoyo.","Agarra ancho y saca un poco el pecho.","Tira de la barra hacia la parte alta del pecho.","Sube despacio hasta estirar los brazos."],t.s)
B.aJX=s(["Tirar detr\xe1s de la nuca.","Echarse muy atr\xe1s para mover m\xe1s peso."],t.s)
B.ap5=new A.cn(B.ax2,B.aJX,"Suelta el aire al subir o empujar.")
B.aCR=s(["Apoya una mano y una rodilla en el banco, espalda plana.","La mancuerna cuelga bajo el hombro.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo por completo."],t.s)
B.ayb=s(["Girar el torso para subir m\xe1s."],t.s)
B.apq=new A.cn(B.aCR,B.ayb,"Suelta el aire al subir o empujar.")
B.aDM=s(["Barra sobre la mitad del pie, espinillas casi toc\xe1ndola.","Cadera atr\xe1s, espalda recta y pecho arriba al agarrar.","Empuja el suelo con las piernas: la barra sube pegada al cuerpo.","Termina erguido, apretando gl\xfateos, sin echarte atr\xe1s."],t.s)
B.awn=s(["Redondear la espalda baja.","Alejar la barra del cuerpo."],t.s)
B.apm=new A.cn(B.aDM,B.awn,"Suelta el aire al subir o empujar.")
B.aJz=s(["De pie, barra a la altura de las clav\xedculas, abdomen y gl\xfateos firmes.","Empuja recto hacia arriba apartando un poco la cabeza.","Arriba, mete la cabeza entre los brazos.","Baja controlado hasta las clav\xedculas."],t.s)
B.aGM=s(["Arquear la espalda baja.","Empujar la barra hacia delante."],t.s)
B.apj=new A.cn(B.aJz,B.aGM,"Suelta el aire al subir o empujar.")
B.av9=s(["De pie, mancuernas a los lados y codos un poco doblados.",u.Y,"Imagina que empujas las paredes, no que subes las manos.","Baja lento, sin dejarlas caer."],t.s)
B.az5=s(["Balancear el cuerpo.","Subir los hombros hacia las orejas."],t.s)
B.aoE=new A.cn(B.av9,B.az5,"Suelta el aire al subir o empujar.")
B.ave=s(["Inclina el torso casi paralelo al suelo con la espalda recta.","Mancuernas colgando, codos un poco doblados.","Abre los brazos hacia los lados apretando la parte de atr\xe1s del hombro.","Baja controlado."],t.s)
B.aF0=s(["Juntar las esc\xe1pulas en vez de mover los brazos."],t.s)
B.ap0=new A.cn(B.ave,B.aF0,"Suelta el aire al subir o empujar.")
B.aEI=s(["De pie, barra con agarre a la anchura de los hombros.","Codos pegados al cuerpo y quietos.","Sube la barra doblando solo los codos.","Baja hasta estirar casi del todo."],t.s)
B.aHS=s(["Balancear el torso.","Adelantar los codos."],t.s)
B.aoL=new A.cn(B.aEI,B.aHS,"Suelta el aire al subir o empujar.")
B.aBQ=s(["Mancuernas con las palmas mir\xe1ndose, como un martillo.","Codos fijos a los lados.","Sube sin girar la mu\xf1eca.","Baja lento."],t.s)
B.aHs=s(["Ayudarse con el hombro."],t.s)
B.ap4=new A.cn(B.aBQ,B.aHs,"Suelta el aire al subir o empujar.")
B.aDj=s(["Frente a la polea alta, codos pegados a las costillas.","Empuja hacia abajo hasta estirar los brazos.","Aprieta el tr\xedceps abajo un instante.","Sube solo hasta que el antebrazo quede horizontal."],t.s)
B.awc=s(["Separar los codos del cuerpo.","Usar el peso del cuerpo."],t.s)
B.aoS=new A.cn(B.aDj,B.awc,"Suelta el aire al subir o empujar.")
B.aKq=s(["Tumbado, barra sobre la frente con los brazos verticales.","Baja doblando solo los codos hacia la frente o detr\xe1s de la cabeza.","Los codos apuntan al techo todo el tiempo.","Extiende hasta estirar los brazos."],t.s)
B.aJu=s(["Abrir los codos hacia los lados."],t.s)
B.ap1=new A.cn(B.aKq,B.aJu,"Suelta el aire al subir o empujar.")
B.aK9=s(["Sentado, antebrazos sobre los muslos y mu\xf1ecas por fuera de las rodillas.","Deja que la barra baje hasta los dedos.","Sube doblando solo la mu\xf1eca.","Movimientos cortos y controlados."],t.s)
B.aJp=s(["Mover los antebrazos."],t.s)
B.aoU=new A.cn(B.aK9,B.aJp,"Suelta el aire al subir o empujar.")
B.azU=s(["Barra sobre la parte alta de la espalda, pies a la anchura de los hombros.","Inspira, aprieta el abdomen y lleva la cadera atr\xe1s y abajo.","Rodillas en la direcci\xf3n de las puntas de los pies.","Baja hasta que el muslo quede paralelo o m\xe1s, y sube empujando el suelo."],t.s)
B.azK=s(["Rodillas hacia dentro.","Levantar los talones.","Redondear la espalda abajo."],t.s)
B.aoJ=new A.cn(B.azU,B.azK,"Suelta el aire al subir o empujar.")
B.aJL=s(["Espalda y cadera pegadas al respaldo.","Pies en el centro de la plataforma, a la anchura de la cadera.","Baja hasta que las rodillas lleguen a unos 90\xb0.","Empuja sin bloquear las rodillas al final."],t.s)
B.aDh=s(["Despegar la cadera abajo.","Bloquear las rodillas de golpe."],t.s)
B.ap_=new A.cn(B.aJL,B.aDh,"Suelta el aire al subir o empujar.")
B.aFs=s(["De pie con las mancuernas a los lados.","Da un paso largo adelante.",u.B,"Empuja con el pie de delante para volver."],t.s)
B.aG5=s(["Paso demasiado corto (la rodilla se pasa mucho)."],t.s)
B.ape=new A.cn(B.aFs,B.aG5,"Suelta el aire al subir o empujar.")
B.aBI=s(["Tumbado boca abajo, el rodillo justo encima de los talones.","Cadera pegada al banco.","Lleva los talones hacia los gl\xfateos.","Baja despacio sin dejar caer el peso."],t.s)
B.aH4=s(["Levantar la cadera para subir."],t.s)
B.aoN=new A.cn(B.aBI,B.aH4,"Suelta el aire al subir o empujar.")
B.aGK=s(["Puntas de los pies en el borde, talones en el aire.","Baja los talones hasta sentir el estiramiento.","Sube todo lo posible sobre las puntas.","Mant\xe9n un segundo arriba."],t.s)
B.aJc=s(["Rebotar abajo.","Doblar las rodillas."],t.s)
B.aoD=new A.cn(B.aGK,B.aJc,"Suelta el aire al subir o empujar.")
B.aF9=s(["Manos (o antebrazos) bajo los hombros, cuerpo en l\xednea recta.","Aprieta abdomen y gl\xfateos.","No dejes caer ni subir la cadera.","Respira normal y aguanta el tiempo marcado."],t.s)
B.avR=s(["Hundir la zona lumbar."],t.s)
B.apg=new A.cn(B.aF9,B.avR,"Respira corto y constante; no aguantes el aire.")
B.aFF=s(["Tumbado boca arriba, manos a los lados o bajo la cadera.","Piernas estiradas y juntas.","S\xfabelas hasta la vertical sin despegar la espalda baja.","B\xe1jalas despacio sin tocar el suelo."],t.s)
B.aBm=s(["Arquear la espalda al bajar."],t.s)
B.ap6=new A.cn(B.aFF,B.aBm,"Suelta el aire al subir o empujar.")
B.aHc=s(["De rodillas, la rueda bajo los hombros.","Aprieta el abdomen y rueda hacia delante despacio.","Llega tan lejos como puedas sin hundir la espalda.","Vuelve tirando con el abdomen, no con los brazos."],t.s)
B.aKG=s(["Dejar caer la cadera."],t.s)
B.aoG=new A.cn(B.aHc,B.aKG,"Suelta el aire al subir o empujar.")
B.aBU=s(["Manos algo m\xe1s anchas que los hombros, cuerpo recto.","Baja el pecho hasta casi tocar el suelo.","Codos a unos 45\xb0 del cuerpo.","Empuja hasta estirar los brazos."],t.s)
B.aBy=s(["Hundir la cadera.","Hacer medio recorrido."],t.s)
B.apn=new A.cn(B.aBU,B.aBy,"Suelta el aire al subir o empujar.")
B.aJr=s(["Manos juntas bajo el pecho formando un rombo con los dedos.","Cuerpo recto de cabeza a talones.","Baja con los codos pegados al cuerpo.","Empuja con los tr\xedceps."],t.s)
B.IE=s(["Abrir los codos."],t.s)
B.aos=new A.cn(B.aJr,B.IE,"Suelta el aire al subir o empujar.")
B.ay5=s(["Sujeta la pesa pegada al pecho con ambas manos.","Pies algo m\xe1s anchos que la cadera.","Baja entre las piernas con el pecho erguido.","Sube empujando el suelo."],t.s)
B.axU=s(["Inclinarse hacia delante."],t.s)
B.aoW=new A.cn(B.ay5,B.axU,"Suelta el aire al subir o empujar.")
B.aEl=s(["Pies a la anchura de los hombros, brazos al frente.","Cadera atr\xe1s y abajo, pecho arriba.","Baja hasta el paralelo o lo que permita tu movilidad.","Sube apretando gl\xfateos."],t.s)
B.axb=s(["Levantar los talones."],t.s)
B.apk=new A.cn(B.aEl,B.axb,"Suelta el aire al subir o empujar.")
B.aFP=s(["De pie, mancuernas delante de los muslos, rodillas apenas flexionadas.","Lleva la cadera atr\xe1s manteniendo la espalda recta.","Baja las pesas pegadas a las piernas hasta sentir los isquios.","Vuelve empujando la cadera adelante."],t.s)
B.awR=s(["Doblar mucho las rodillas (se vuelve sentadilla)."],t.s)
B.aox=new A.cn(B.aFP,B.awR,"Suelta el aire al subir o empujar.")
B.aIr=s(["Mancuernas a la altura de los hombros, palmas al frente.","Abdomen firme.","Empuja hacia arriba hasta casi juntarlas.","Baja controlado."],t.s)
B.I6=s(["Arquear la espalda baja."],t.s)
B.aoz=new A.cn(B.aIr,B.I6,"Suelta el aire al subir o empujar.")
B.azh=s(["Mancuernas a los lados, palmas al frente.","Codos fijos.","Sube girando ligeramente la mu\xf1eca hacia fuera.","Baja lento."],t.s)
B.aHW=s(["Balancearse."],t.s)
B.aow=new A.cn(B.azh,B.aHW,"Suelta el aire al subir o empujar.")
B.aKx=s(["Sujeta una mancuerna con ambas manos sobre la cabeza.","Baja detr\xe1s de la cabeza doblando solo los codos.","Codos apuntando al techo.","Extiende hasta estirar los brazos."],t.s)
B.apo=new A.cn(B.aKx,B.IE,"Suelta el aire al subir o empujar.")
B.aHi=s(["Sentado, piernas estiradas y la banda alrededor de los pies.","Espalda recta y pecho arriba.","Tira llevando los codos atr\xe1s pegados al cuerpo.","Vuelve despacio sin redondear la espalda."],t.s)
B.ayt=s(["Echarse atr\xe1s con el torso."],t.s)
B.ap9=new A.cn(B.aHi,B.ayt,"Suelta el aire al subir o empujar.")
B.azr=s(["Tumbado boca arriba, rodillas dobladas y pies en el suelo.","Empuja con los talones y sube la cadera.","Arriba, el cuerpo forma una l\xednea de hombros a rodillas.","Aprieta gl\xfateos un segundo y baja."],t.s)
B.Iy=s(["Arquear la espalda en vez de usar el gl\xfateo."],t.s)
B.apc=new A.cn(B.azr,B.Iy,"Suelta el aire al subir o empujar.")
B.aDE=s(["De pie en el borde de un escal\xf3n, ap\xf3yate en la pared.","Baja los talones para estirar.","Sube todo lo posible sobre las puntas.","Hazlo lento: aqu\xed la calidad lo es todo."],t.s)
B.aEL=s(["Rebotar."],t.s)
B.aoX=new A.cn(B.aDE,B.aEL,"Suelta el aire al subir o empujar.")
B.aF_=s(["Tumbado, rodillas dobladas, manos en las sienes.","Despega los hombros del suelo enrollando la columna.","Mira al techo, no tires del cuello.","Baja controlado."],t.s)
B.ay9=s(["Tirar de la cabeza con las manos."],t.s)
B.aoR=new A.cn(B.aF_,B.ay9,"Suelta el aire al subir o empujar.")
B.aFt=s(["Rodillas en el suelo (o en un coj\xedn) y manos algo m\xe1s anchas que los hombros.","Cuerpo recto de rodillas a cabeza: no dobles la cadera.","Baja el pecho hasta casi tocar el suelo.","Empuja hasta estirar los brazos."],t.s)
B.aIw=s(["Sacar el trasero hacia arriba.","Bajar solo la cabeza."],t.s)
B.apl=new A.cn(B.aFt,B.aIw,"Suelta el aire al subir o empujar.")
B.azy=s(["Manos en el asiento de una silla firme contra la pared, o en el sof\xe1.","Pies atr\xe1s, cuerpo recto de talones a cabeza.","Baja el pecho hasta el borde del asiento.","Empuja. Cuanto m\xe1s baja la superficie, m\xe1s dif\xedcil."],t.s)
B.aIo=s(["Usar una silla que se desliza.","Hundir la cadera."],t.s)
B.aoF=new A.cn(B.azy,B.aIo,"Suelta el aire al subir o empujar.")
B.aEo=s(["Pies sobre una silla o el sof\xe1, manos en el suelo bajo los hombros.","Abdomen y gl\xfateos firmes: el cuerpo es una tabla.","Baja hasta casi tocar el suelo con la frente por delante de las manos.","Empuja hasta estirar los brazos."],t.s)
B.aHn=s(["Dejar caer la cadera.","Abrir los codos en cruz."],t.s)
B.aoK=new A.cn(B.aEo,B.aHn,"Suelta el aire al subir o empujar.")
B.aFx=s(["T\xfambate bajo una mesa ROBUSTA y agarra el borde con las dos manos.","Talones apoyados y cadera arriba, en l\xednea con los hombros.","Tira llevando el pecho hacia el borde y los codos hacia el suelo.","Baja despacio hasta estirar los brazos."],t.s)
B.aB1=s(["Usar una mesa ligera o con patas plegables.","Dejar caer la cadera."],t.s)
B.aoO=new A.cn(B.aFx,B.aB1,"Suelta el aire al subir el pecho.")
B.aIe=s(["Boca abajo, brazos estirados al frente y piernas juntas.","Mira al suelo para no forzar el cuello.","Despega a la vez brazos, pecho y piernas unos cent\xedmetros.","Aguanta dos segundos arriba y baja con control."],t.s)
B.azG=s(["Levantar la cabeza mirando al frente.","Subir de golpe."],t.s)
B.ap8=new A.cn(B.aIe,B.azG,"Suelta el aire al subir o empujar.")
B.aKa=s(["Una garrafa de 5 L pesa 5 kg; una mochila con libros, lo que le metas.","Inclina el torso con la espalda recta y apoya la otra mano en una silla.","Tira llevando el codo hacia la cadera.","Baja hasta estirar el brazo y cambia de lado al acabar la serie."],t.s)
B.aKJ=s(["Girar el torso para subir.","Asas que se clavan: envu\xe9lvelas en una toalla."],t.s)
B.ap3=new A.cn(B.aKa,B.aKJ,"Suelta el aire al subir o empujar.")
B.ay2=s(["Forma una V invertida: cadera arriba, manos y pies en el suelo.","Acerca los pies a las manos todo lo que te permita la flexibilidad.","Baja la cabeza hacia el suelo, por delante de las manos.","Empuja hasta estirar los brazos. Es un press de hombro sin pesas."],t.s)
B.aG4=s(["Bajar la cadera y convertirla en una flexi\xf3n normal."],t.s)
B.apb=new A.cn(B.ay2,B.aG4,"Suelta el aire al subir o empujar.")
B.aF8=s(["Pisa la banda con los dos pies y agarra los extremos a la altura de los hombros.","Abdomen firme y gl\xfateos apretados.","Empuja hacia arriba hasta estirar los brazos.","Baja despacio: la banda tira, no la dejes ganar."],t.s)
B.aou=new A.cn(B.aF8,B.I6,"Suelta el aire al subir o empujar.")
B.aIE=s(["Una botella de agua en cada mano (1,5 L \u2248 1,5 kg).","Codos un poco doblados y hombros lejos de las orejas.",u.Y,"Baja en tres segundos."],t.s)
B.aAm=s(["Balancear el cuerpo.","Subir m\xe1s arriba de los hombros."],t.s)
B.app=new A.cn(B.aIE,B.aAm,"Suelta el aire al subir o empujar.")
B.aL5=s(["Pisa la banda con los pies a la anchura de la cadera.","Codos pegados al cuerpo y quietos.","Sube doblando solo los codos.","Baja despacio hasta estirar."],t.s)
B.axc=s(["Adelantar los codos.","Echarse atr\xe1s para ayudarse."],t.s)
B.aoC=new A.cn(B.aL5,B.axc,"Suelta el aire al subir o empujar.")
B.aL4=s(["Agarra la garrafa por el asa con el brazo estirado.","Codo pegado al costado.","Sube doblando el codo hasta el hombro.","Baja lento. Cambia de mano en cada serie."],t.s)
B.aBn=s(["Balancear el torso."],t.s)
B.apa=new A.cn(B.aL4,B.aBn,"Suelta el aire al subir o empujar.")
B.aCg=s(["Silla firme contra la pared. Manos en el borde del asiento, dedos al frente.","Piernas estiradas (m\xe1s dif\xedcil) o dobladas (m\xe1s f\xe1cil).","Baja doblando los codos hacia atr\xe1s hasta unos 90\xb0.","Empuja hasta estirar los brazos."],t.s)
B.aA8=s(["Bajar demasiado si te molesta el hombro.","Abrir los codos hacia fuera."],t.s)
B.ap7=new A.cn(B.aCg,B.aA8,"Suelta el aire al subir o empujar.")
B.aGG=s(["Sentado, antebrazo sobre el muslo y la mu\xf1eca por fuera de la rodilla.","Deja que la garrafa baje con la mu\xf1eca.","Sube doblando solo la mu\xf1eca.","Recorridos cortos y lentos."],t.s)
B.axe=s(["Mover el antebrazo."],t.s)
B.aoP=new A.cn(B.aGG,B.axe,"Suelta el aire al subir o empujar.")
B.aJ5=s(["Una garrafa o mochila pesada en cada mano.","Hombros atr\xe1s y abajo, pecho arriba, abdomen firme.","Camina por la casa (o marcha en el sitio) a pasos cortos.","Aprieta las asas durante todo el tiempo marcado."],t.s)
B.azv=s(["Encorvarse hacia delante.","Inclinarse hacia un lado."],t.s)
B.aov=new A.cn(B.aJ5,B.azv,"Respira corto y constante mientras caminas.")
B.aJf=s(["Posici\xf3n de flexi\xf3n, manos bajo los hombros.","Lleva una rodilla hacia el pecho y vuelve.","Alterna las piernas a buen ritmo sin subir la cadera.","Cada rodilla que llega al pecho cuenta como una repetici\xf3n."],t.s)
B.aFb=s(["Levantar la cadera.","Rebotar con los hombros."],t.s)
B.aoV=new A.cn(B.aJf,B.aFb,"Respira r\xedtmico, sin aguantar el aire.")
B.aHX=s(["Boca arriba, manos bajo la cadera y la espalda baja pegada al suelo.","Piernas estiradas y algo despegadas del suelo.","Sube y baja las piernas alternando, como unas tijeras.","Movimientos cortos y controlados."],t.s)
B.aCY=s(["Despegar la espalda baja del suelo."],t.s)
B.aoA=new A.cn(B.aHX,B.aCY,"Suelta el aire al subir o empujar.")
B.aCP=s(["De pie, manos en la cintura.","Da un paso largo hacia atr\xe1s.",u.B,"Vuelve empujando con el pie de delante."],t.s)
B.avk=s(["Dejar que la rodilla de delante se vaya hacia dentro."],t.s)
B.ap2=new A.cn(B.aCP,B.avk,"Suelta el aire al subir o empujar.")
B.aw8=s(["De espaldas a una silla firme, apoya el empeine de un pie en el asiento.","El pie de delante, a un paso largo de la silla.","Baja recto hasta que el muslo de delante quede casi paralelo.","Sube empujando con el tal\xf3n de delante."],t.s)
B.aAy=s(["Pie de delante demasiado cerca de la silla.","Inclinarse hacia un lado."],t.s)
B.aoH=new A.cn(B.aw8,B.aAy,"Suelta el aire al subir o empujar.")
B.aGP=s(["Espalda pegada a la pared, pies un paso por delante.","Baja hasta que los muslos queden paralelos al suelo.","Rodillas sobre los tobillos, no por delante.","Aguanta el tiempo marcado."],t.s)
B.ay7=s(["Apoyar las manos en las piernas para descargar."],t.s)
B.aoQ=new A.cn(B.aGP,B.ay7,"Respira lento; no aguantes el aire.")
B.aBo=s(["Usa un escal\xf3n o un caj\xf3n estable, nunca una silla con ruedas.","Apoya el pie entero arriba.","Sube empujando solo con esa pierna y eleva la otra rodilla.","Baja despacio. Repite y cambia de lado."],t.s)
B.awk=s(["Impulsarse con la pierna de abajo."],t.s)
B.aoY=new A.cn(B.aBo,B.awk,"Suelta el aire al subir o empujar.")
B.avb=s(["Pies a la anchura de los hombros.","Baja a una sentadilla con los brazos atr\xe1s.","Salta lanzando los brazos arriba.","Aterriza suave, sobre la punta y luego el tal\xf3n, ya bajando a la siguiente."],t.s)
B.aE5=s(["Caer con las rodillas r\xedgidas.","Rodillas hacia dentro al aterrizar."],t.s)
B.aot=new A.cn(B.avb,B.aE5,"Suelta el aire al saltar.")
B.aC7=s(["Boca arriba, un pie en el suelo y la otra pierna estirada al aire.","Empuja con el tal\xf3n y sube la cadera.","Arriba, cadera recta: que no se caiga hacia un lado.","Baja despacio. Cambia de pierna."],t.s)
B.aoB=new A.cn(B.aC7,B.Iy,"Suelta el aire al subir o empujar.")
B.aE2=s(["Punta de un pie en el borde de un escal\xf3n; ap\xf3yate en la pared.","Baja el tal\xf3n hasta estirar.","Sube todo lo que puedas sobre la punta.","Lento arriba y abajo. Cambia de pierna."],t.s)
B.aHe=s(["Rebotar abajo."],t.s)
B.aph=new A.cn(B.aE2,B.aHe,"Suelta el aire al subir o empujar.")
B.aFK=s(["De pie, rodillas casi estiradas y manos como si sujetaras una comba.","Salta solo con los tobillos, a pocos cent\xedmetros del suelo.","Aterriza sobre la punta, sin apoyar el tal\xf3n.","Cuenta los saltos o hazlos por tiempo."],t.s)
B.aFC=s(["Doblar mucho las rodillas.","Hacer ruido al caer: aterriza suave."],t.s)
B.aoM=new A.cn(B.aFK,B.aFC,"Respira r\xedtmico.")
B.avV=s(["De pie, pies juntos y brazos a los lados.","Salta abriendo las piernas y subiendo los brazos por encima de la cabeza.","Salta de nuevo para volver a cerrar.","Mant\xe9n un ritmo que puedas sostener."],t.s)
B.avc=s(["Aterrizar sobre los talones."],t.s)
B.aoT=new A.cn(B.avV,B.avc,"Respira r\xedtmico, sin aguantar el aire.")
B.aO9=new A.b9(B.Oi,[B.aoy,B.api,B.apf,B.apd,B.aoI,B.aoZ,B.ap5,B.apq,B.apm,B.apj,B.aoE,B.ap0,B.aoL,B.ap4,B.aoS,B.ap1,B.aoU,B.aoJ,B.ap_,B.ape,B.aoN,B.aoD,B.apg,B.ap6,B.aoG,B.apn,B.aos,B.aoW,B.apk,B.aox,B.aoz,B.aow,B.apo,B.ap9,B.apc,B.aoX,B.aoR,B.apl,B.aoF,B.aoK,B.aoO,B.ap8,B.ap3,B.apb,B.aou,B.app,B.aoC,B.apa,B.ap7,B.aoP,B.aov,B.aoV,B.aoA,B.ap2,B.aoH,B.aoQ,B.aoY,B.aot,B.aoB,B.aph,B.aoM,B.aoT],A.am("b9<p,cn>"))
B.aOa=new A.b9(B.Oi,[B.PX,B.Q2,B.Q0,B.Py,B.Px,B.qQ,B.Q4,B.qQ,B.PD,B.qP,B.yx,B.Q_,B.kX,B.kX,B.Pz,B.PB,B.yu,B.Pw,B.PC,B.yv,B.PE,B.qO,B.PF,B.PG,B.PH,B.yt,B.yt,B.ys,B.ys,B.PM,B.qP,B.kX,B.PA,B.Q3,B.yw,B.qO,B.PI,B.PJ,B.PK,B.PL,B.PP,B.PQ,B.qQ,B.PN,B.qP,B.yx,B.kX,B.kX,B.PO,B.yu,B.PY,B.PV,B.PW,B.yv,B.PR,B.PS,B.PT,B.PU,B.yw,B.qO,B.PZ,B.Q1],A.am("b9<p,d1>"))
B.aPl={flexiones_rodillas:0,flexiones_inclinadas:1,flexiones:2,flexiones_declinadas:3,sentadilla_libre:4,zancada_atras:5,sentadilla_bulgara:6,puente_gluteo:7,talones_libre:8,crunch:9,elevaciones_botellas:10,fondos_silla:11,superman:12}
B.aOb=new A.b9(B.aPl,["flexiones_inclinadas","flexiones","flexiones_declinadas","flexiones_diamante","zancada_atras","sentadilla_bulgara","sentadilla_salto","puente_una_pierna","talones_una_pierna","elevacion_piernas","flexiones_pica","flexiones_diamante","remo_mesa"],t.li)
B.aPE={KeyA:0,KeyB:1,KeyC:2,KeyD:3,KeyE:4,KeyF:5,KeyG:6,KeyH:7,KeyI:8,KeyJ:9,KeyK:10,KeyL:11,KeyM:12,KeyN:13,KeyO:14,KeyP:15,KeyQ:16,KeyR:17,KeyS:18,KeyT:19,KeyU:20,KeyV:21,KeyW:22,KeyX:23,KeyY:24,KeyZ:25,Digit1:26,Digit2:27,Digit3:28,Digit4:29,Digit5:30,Digit6:31,Digit7:32,Digit8:33,Digit9:34,Digit0:35,Minus:36,Equal:37,BracketLeft:38,BracketRight:39,Backslash:40,Semicolon:41,Quote:42,Backquote:43,Comma:44,Period:45,Slash:46}
